begin;
select plan(27);
insert into auth.users(id) values('00000000-0000-0000-0000-000000000001'),('00000000-0000-0000-0000-000000000002');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
select is((select count(*)::int from public.current_service_terms()),0,'no published legal text means unavailable');
select throws_ok($$ select public.create_personal_group('Test only') $$,'42501','current service terms acceptance required','RPC cannot bypass acceptance');
select throws_ok($$ select public.accept_service_terms('client-invented') $$,'42501','terms changed; read current version','client cannot invent version');
reset role;
insert into public.service_terms(version,body,document_url,document_sha256,current) values('fixture-v1','TEST ONLY','https://example.test/terms',repeat('a',64),true);
-- TEST-ONLY literal rule; no production policy/approval.
insert into public.content_moderation_policies(version,terms_version,denied_phrases,policy_document_url,policy_document_sha256,current) values('fixture-policy-v1','fixture-v1',array['QA-BLOCKED-TEXT'],'https://example.test/policy',repeat('c',64),true);

set local role authenticated;
select is((select version from public.current_service_terms()),'fixture-v1','server chooses current version');
select ok((select accepted_at is null from public.current_service_terms()),'initially not accepted');
select throws_ok($$ insert into public.service_terms_acceptances(user_id,terms_version,accepted_at) values(auth.uid(),'fixture-v1','2000-01-01') $$,'42501',null,'direct forged acceptance denied');
select throws_ok($$ update public.service_terms set current=false $$,'42501',null,'client cannot publish version');
select lives_ok($$ select public.accept_service_terms('fixture-v1') $$,'valid version accepted');
select ok((select accepted_at between transaction_timestamp() and clock_timestamp() from public.current_service_terms()),'timestamp assigned by server');
select lives_ok($$ select public.accept_service_terms('fixture-v1') $$,'acceptance retry is idempotent');
select is((select count(*)::int from public.service_terms_acceptances),1,'retry has one record');
select lives_ok($$ select public.create_personal_group('Accepted fixture') $$,'accepted user can create group');
select set_config('fixture.group_id',(select id::text from public.groups limit 1),true);
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
select is((select count(*)::int from public.service_terms_acceptances),0,'account switch cannot see other acceptance');
select throws_ok($$ select public.create_personal_group('Other account') $$,'42501','current service terms acceptance required','account switch requires own acceptance');
reset role;
select throws_ok($$ update public.service_terms set body='changed' where version='fixture-v1' $$,'22023','publish a new terms version','accepted text immutable even for operator');
insert into public.device_push_tokens(user_id,platform,token) values('00000000-0000-0000-0000-000000000001','android','TEST_ONLY_TOKEN');
update public.service_terms set current=false;
insert into public.service_terms(version,body,document_url,document_sha256,current) values('fixture-v2','TEST ONLY NEW','https://example.test/terms/v2',repeat('b',64),true);
update public.content_moderation_policies set current=false;
insert into public.content_moderation_policies(version,terms_version,denied_phrases,policy_document_url,policy_document_sha256,current) values('fixture-policy-v2','fixture-v2',array['QA-BLOCKED-TEXT'],'https://example.test/policy/v2',repeat('d',64),true);
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
select ok((select accepted_at is null from public.current_service_terms()),'old acceptance not applied to new version');
select throws_ok($$ select public.accept_service_terms('fixture-v1') $$,'42501','terms changed; read current version','stale offline acceptance denied');
select throws_ok($$ insert into public.messages(group_id,sender_id,client_id,body) select id,auth.uid(),gen_random_uuid(),'stale offline outbox' from public.groups $$,'42501','current service terms acceptance required','offline outbox rejected server-side after update');
select lives_ok($$ update public.device_push_tokens set enabled=false where user_id=auth.uid() $$,'token revocation remains available without new acceptance');
select lives_ok($$ delete from public.device_push_tokens where user_id=auth.uid() $$,'token delete remains available without new acceptance');
select lives_ok($$ select public.accept_service_terms('fixture-v2') $$,'new version requires explicit acceptance');
insert into public.messages(group_id,sender_id,client_id,body) values(current_setting('fixture.group_id')::uuid,auth.uid(),gen_random_uuid(),'visible before revocation');
reset role;
update public.group_members set status='removed' where user_id='00000000-0000-0000-0000-000000000001';
set local role authenticated;
select throws_ok($$ insert into public.messages(group_id,sender_id,client_id,body) values(current_setting('fixture.group_id')::uuid,auth.uid(),gen_random_uuid(),'removed member') $$,'42501',null,'acceptance does not restore revoked membership');
select is((select count(*)::int from public.messages),0,'revoked membership still hides message history');
select is((select count(*)::int from public.service_terms_acceptances),2,'membership change does not erase consent history');
select lives_ok($$ insert into public.account_deletion_requests(user_id) values(auth.uid()) $$,'deletion request available');
select throws_ok($$ select public.accept_service_terms('fixture-v2') $$,'42501','account deletion pending','pending deletion cannot renew service consent');
reset role;
select is((select count(*)::int from public.service_terms_acceptances where user_id='00000000-0000-0000-0000-000000000001'),2,'version history retained until account deletion');
select * from finish();
rollback;
